nonzero_command_exits.command:
/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { renameProject } from './subject.mjs';
const cases = [
  ['same organization', {organizationId:'a'}, 'p', 'new', 200, 'new'],
  ['other organization', {organizationId:'b'}, 'p', 'new', 403, 'old'],
  ['missing project', {organizationId:'a'}, 'missing', 'new', 404, 'old'],
  ['empty title', {organizationId:'a'}, 'p', '', 400, 'old'],
  ['number title', {organizationId:'a'}, 'p', 0, 400, 'old'],
  ['null title', {organizationId:'a'}, 'p', null, 400, 'old'],
  ['object title', {organizationId:'a'}, 'p', {}, 400, 'old'],
  ['array title', {organizationId:'a'}, 'p', [], 400, 'old'],
  ['boolean title', {organizationId:'a'}, 'p', false, 400, 'old'],
  ['whitespace is valid', {organizationId:'a'}, 'p', ' ', 200, ' '],
];
let failures = 0;
for (const [name,user,id,title,status,expectedTitle] of cases) {
  const project = {organizationId:'a',title:'old'};
  const other = {organizationId:'b',title:'untouched'};
  const projects = new Map([['p',project],['other',other]]);
  const result = renameProject(user,id,title,projects);
  try {
    assert.deepEqual(result,{status});
    assert.deepEqual(project,{organizationId:'a',title:expectedTitle});
    assert.deepEqual(other,{organizationId:'b',title:'untouched'});
    assert.equal(projects.size,2);
    assert.equal(projects.get('p'),project);
    console.log('PASS',name);
  } catch (error) {
    failures++;
    console.log('FAIL',name,JSON.stringify({expected:{status,title:expectedTitle},actual:{status:result.status,title:project.title}}));
  }
}
process.exitCode = failures ? 1 : 0;
JS"
